	} catch (err) {
		throw new Error(`Graphviz could not be found. Ensure that "gvpr" is in your $PATH. ${err}`);
	}
}

/**
 * Return options to use with graphviz digraph.
 * @param  {Object} config
 * @return {Object}
 */
